.skh-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #fff);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #000);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.skh-root,.skh-root *,.skh-root *::before,.skh-root *::after{box-sizing:border-box}
.skh-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.skh-root img{display:block;border:0;max-width:none}
.skh-root .n64_3712{align-content:stretch;display:flex;flex-direction:column;gap:52px;align-items:center;position:relative;flex-shrink:0}
.skh-root .n64_3713{align-content:stretch;display:flex;gap:2px;align-items:baseline;justify-content:flex-end;position:relative;flex-shrink:0;width:100%}
.skh-root .n64_3714{align-content:stretch;display:flex;align-items:center;justify-content:flex-end;position:relative;flex-shrink:0}
.skh-root .n64_3715{word-break:break-word;font-family:"Tomorrow","Pretendard",system-ui,sans-serif;font-weight:500;line-height:29px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #313131);font-size:24px;text-align:right;letter-spacing:-0.96px;white-space:nowrap;width:46px}
.skh-root .n64_3716{align-content:stretch;display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;flex-shrink:0}
.skh-root .n64_3717{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:29px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #888);font-size:24px;white-space:nowrap;width:11px}
.skh-root .n64_3718{align-content:stretch;display:flex;flex-direction:column;gap:12px;align-items:center;position:relative;flex-shrink:0}
.skh-root .n64_3719{align-content:stretch;display:flex;gap:6px;align-items:flex-end;position:relative;flex-shrink:0}
.skh-root .n64_3720{height:62px;position:relative;border-radius:2px;flex-shrink:0;width:8px;box-shadow:3px 5px 5px 0px rgba(245,156,66,0.5);background-image:linear-gradient(to top,var(--wa-warn, #ffc410),var(--wa-warn, #f89363))}
.skh-root .n64_3721{height:59px;position:relative;border-radius:2px;flex-shrink:0;width:8px;box-shadow:3px 5px 5px 0px rgba(159,156,157,0.5);background-image:linear-gradient(to top,var(--wa-surface, #9f9c9d),var(--wa-surface, #7d7c7d))}
.skh-root .n64_3722{align-content:stretch;display:flex;align-items:center;justify-content:center;position:relative;flex-shrink:0}
.skh-root .n64_3723{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:14px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #888);font-size:12px;white-space:nowrap;width:48px}
.skh-root[data-theme="dark"] .n64_3715{color:var(--wa-text, #eceffa)}
.skh-root[data-theme="dark"] .n64_3717{color:var(--wa-text-sub, #9199b1)}
.skh-root[data-theme="dark"] .n64_3721{background-image:linear-gradient(to top,var(--wa-surface, #9aa2b6),var(--wa-surface, #6c7391))}
